<?php
declare(strict_types=1);
require_once __DIR__.'/fixtures/ShopAccessFixture.php';
require_once __DIR__.'/PortalActionAcceptanceFixture.php';
use DigiForge\Database\Tables;

/** Seeded source records and native decisions, with no marketplace or finance authority. */
final class PortalSourceWorkflowAcceptanceTest extends WP_UnitTestCase {
 private int $httpCalls=0;
 private mixed $httpGuard;
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();DigiForge\Core\Settings::protectProduction();ShopAccessFixture::reset();wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));ShopAccessFixture::authorizeActor(get_current_user_id(),['digital','personalized_pod','standard_pod','jewelry'],DigiForge\Core\Capabilities::ALL);$this->httpGuard=function(){++$this->httpCalls;return new WP_Error('offline_portal_source','HTTP forbidden.');};add_filter('pre_http_request',$this->httpGuard,10,3);}
 protected function tearDown():void {remove_filter('pre_http_request',$this->httpGuard,10);self::assertSame(0,$this->httpCalls);self::assertTrue(DigiForge\Core\Settings::get('stop_all',true));self::assertFalse(DigiForge\Core\Settings::get('automation_armed',false));parent::tearDown();}
 private function render(string $view,string $shop,array $focus=[]):string {$before=$_GET;try{$_GET=['df_view'=>$view,'df_shop'=>$shop]+$focus;return (new DigiForge\Portal\Portal())->render();}finally{$_GET=$before;}}
 private function candidate(string $shop,string $marker):array {
  $repo=new DigiForge\Research\Repository();$source=$repo->createSource(['shop_key'=>$shop,'name'=>$marker.' source','source_type'=>'manual','environment'=>'sandbox']);self::assertNotWPError($source);$url='https://example.invalid/'.$marker;
  $observation=$repo->ingest(['source_id'=>$source['id'],'title'=>$marker.' observation','body'=>$marker.' observed evidence','provenance'=>['url'=>$url]]);self::assertNotWPError($observation);
  $evidence=$repo->addEvidence((int)$observation['id'],['evidence_type'=>'manual_note','value'=>$marker.' source fact']);self::assertNotWPError($evidence);
  $candidate=$repo->createCandidate(['shop_key'=>$shop,'title'=>$marker.' opportunity','summary'=>$marker.' summary','signals'=>['demand'=>82,'competition'=>31]]);self::assertNotWPError($candidate);self::assertTrue($repo->linkEvidence((int)$candidate['id'],(int)$evidence['id']));return compact('candidate','source','observation','evidence','url','marker','shop');
 }
 private function product(array $research):array {
  $repo=new DigiForge\Research\Repository();self::assertNotWPError($repo->review((int)$research['candidate']['id'],'APPROVED','Synthetic source fixture only.'));$opportunity=$repo->promote((int)$research['candidate']['id']);self::assertNotWPError($opportunity);$factory=new DigiForge\ProductFactory\Repository();$marker=$research['marker'];
  $family=$factory->create('product_family',['opportunity_id'=>$opportunity['id'],'name'=>$marker.' family']);self::assertNotWPError($family);$product=$factory->create('product',['product_family_id'=>$family['id'],'name'=>$marker.' canonical product']);self::assertNotWPError($product);$version=$factory->create('product_version',['product_id'=>$product['id'],'version_label'=>$marker.'-v1']);self::assertNotWPError($version);self::assertNotWPError($factory->transition('product_version',(int)$version['id'],'REVIEW'));self::assertNotWPError($factory->transition('product_version',(int)$version['id'],'APPROVED'));return $research+compact('opportunity','family','product','version');
 }
 private function listing(array $flow):array {
  $listing=(new DigiForge\Listings\Repository())->createListing(['product_version_id'=>$flow['version']['id'],'channel'=>'etsy','environment'=>'sandbox','shop_reference'=>$flow['shop'],'title'=>$flow['marker'].' listing','description'=>'Synthetic portal evidence','currency'=>'USD','price_amount'=>1]);self::assertNotWPError($listing);return $listing;
 }
 private function unknown(array $flow):array {
  $listing=$this->listing($flow);global $wpdb;$now=current_time('mysql',true);$hash=hash('sha256',$flow['marker']);self::assertSame(1,$wpdb->insert(Tables::etsy_draft_packages(),['listing_id'=>$listing['id'],'package_version'=>'v1','canonical_payload'=>'{}','payload_hash'=>$hash,'readiness'=>'{}','readiness_hash'=>$hash,'approved_by'=>get_current_user_id(),'approved_at'=>$now,'created_at'=>$now]));$package=(int)$wpdb->insert_id;
  self::assertSame(1,$wpdb->insert($wpdb->prefix.'digiforge_etsy_operations',['shop_reference'=>$flow['shop'],'intent_id'=>1,'draft_package_id'=>$package,'operation_type'=>'CREATE_DRAFT','state'=>'UNKNOWN','resource_reference'=>$flow['marker'].'-unknown-resource','idempotency_key'=>$flow['marker'].'-unknown','request_fingerprint'=>$hash,'authorization_hash'=>$hash,'evidence_hash'=>$hash,'created_at'=>$now,'updated_at'=>$now]));return ['operation_id'=>(int)$wpdb->insert_id,'listing'=>$listing];
 }
 public function testResearchSourceFactsScoresLinksAndNativeApprovalRetainSelectedCatalogLineage():void {
  $own=$this->candidate('digital','portal-own-'.wp_rand());$foreign=$this->candidate('jewelry','portal-foreign-'.wp_rand());$html=$this->render('research','digital');foreach([$own['candidate']['title'],$own['evidence']['value'],$own['observation']['title'],$own['url'],number_format((float)$own['candidate']['score'],2)]as $value)self::assertStringContainsString(esc_html((string)$value),$html);self::assertStringNotContainsString($foreign['marker'],$html);self::assertStringContainsString('name="candidate_id" value="'.$own['candidate']['id'].'"',$html);
  PortalActionAcceptanceFixture::invoke('REVIEW_ACTION',['candidate_id'=>$own['candidate']['id'],'decision'=>'APPROVED','notes'=>'Portal reviewed exact source facts']);global $wpdb;self::assertSame('APPROVED',$wpdb->get_var($wpdb->prepare('SELECT review_status FROM '.Tables::research_candidates().' WHERE id=%d',$own['candidate']['id'])));$html=$this->render('research','digital');self::assertStringContainsString('digiforge_portal_develop_candidate',$html);preg_match_all('/<article class="df-candidate">.*?<\/article>/s',$html,$cards);$ownCards=array_values(array_filter($cards[0],static fn(string $card):bool=>str_contains($card,$own['candidate']['title'])));self::assertCount(1,$ownCards);self::assertStringNotContainsString('name="decision" value="APPROVED"',$ownCards[0]);
  $flow=$this->product($own);$other=$this->product($foreign);$html=$this->render('products','digital');foreach([$flow['family']['name'],$flow['product']['name'],$flow['version']['version_label']]as $value)self::assertStringContainsString(esc_html($value),$html);self::assertStringNotContainsString($other['marker'],$html);self::assertMatchesRegularExpression('/value="digital"\s+selected=/',$html);foreach(['digital','personalized_pod','standard_pod','jewelry']as $shop)self::assertStringContainsString('value="'.$shop.'"',$html);
 }
 public function testDigitalFilesVersionsPreviewsAndProductionAssetRecordsRenderExactStoredScope():void {
  $own=$this->product($this->candidate('digital','portal-digital-'.wp_rand()));$other=$this->product($this->candidate('jewelry','portal-other-'.wp_rand()));$repo=new DigiForge\DigitalFactory\Repository();$rows=[];
  foreach([$own,$other]as $flow){$digital=$repo->create('digital_product',['product_id'=>$flow['product']['id'],'product_version_id'=>$flow['version']['id'],'name'=>$flow['marker'].' digital','category'=>'offline']);self::assertNotWPError($digital);$file=$repo->create('digital_file',['digital_product_id'=>$digital['id'],'product_version_id'=>$flow['version']['id'],'name'=>$flow['marker'].' file','file_type'=>'txt']);self::assertNotWPError($file);$version=$repo->create('digital_file_version',['digital_file_id'=>$file['id'],'version_label'=>$flow['marker'].'-file-v1']);self::assertNotWPError($version);$preview=$repo->create('digital_preview',['digital_product_id'=>$digital['id'],'digital_file_id'=>$file['id'],'name'=>$flow['marker'].' preview']);self::assertNotWPError($preview);$rows[$flow['shop']]=compact('digital','file','version','preview');}
  // Missing recorded QA must be shown on an actual check row, not inferred from product state.
  $missing=$repo->create('digital_download_check',['digital_product_id'=>$rows['digital']['digital']['id'],'target_type'=>'file_version','target_id'=>$rows['digital']['version']['id'],'check_type'=>'custom_deterministic_qa','validation_result'=>'FAIL','review_status'=>'UNREVIEWED','details'=>[]]);self::assertNotWPError($missing);
  $html=$this->render('digital','digital');foreach([$rows['digital']['digital']['name'],$rows['digital']['file']['name'],$rows['digital']['version']['version_label'],$rows['digital']['preview']['name']]as $value)self::assertStringContainsString(esc_html($value),$html);self::assertStringNotContainsString($other['marker'],$html);self::assertStringContainsString('UNVERIFIED',$html);self::assertStringContainsString('df_view=approvals',$html);
  $production=new DigiForge\Production\Repository();$spec=$production->createSpec(['product_version_id'=>$own['version']['id'],'digital_product_id'=>$rows['digital']['digital']['id'],'asset_key'=>'portal-asset-'.wp_rand(),'asset_type'=>'print','purpose'=>$own['marker'].' design','format'=>'png','width_px'=>800,'height_px'=>1000,'dpi'=>300]);self::assertNotWPError($spec);$plan=$production->createPlan(['product_version_id'=>$own['version']['id'],'plan_key'=>'portal-plan-'.wp_rand(),'version_label'=>$own['marker'].'-plan-v1','channel'=>'digital','production_type'=>'deterministic']);self::assertNotWPError($plan);self::assertTrue($production->linkAsset((int)$plan['id'],(int)$spec['id']));$html=$this->render('production','digital');foreach([$spec['asset_key'],$spec['purpose'],$plan['plan_key'],$plan['version_label']]as $value)self::assertStringContainsString(esc_html($value),$html);self::assertStringNotContainsString($other['marker'],$html);
 }
 public function testListingGateShowsExactBlockedEvidenceAndRejectsDecisionWithoutChangingStoredListing():void {
  $flow=$this->product($this->candidate('digital','portal-gate-'.wp_rand()));$listing=$this->listing($flow);$other=$this->listing($this->product($this->candidate('jewelry','portal-hidden-gate-'.wp_rand())));global $wpdb;$now=current_time('mysql',true);$readiness=(new DigiForge\Listings\Repository())->readiness((int)$listing['id']);self::assertNotWPError($readiness);self::assertSame(1,$wpdb->insert(Tables::listing_readiness_reviews(),['listing_id'=>$listing['id'],'readiness'=>DigiForge\Listings\Validator::canonicalJson($readiness),'readiness_hash'=>$readiness['hash'],'decision'=>'PENDING','created_at'=>$now,'updated_at'=>$now]));$id=(int)$wpdb->insert_id;
  $html=$this->render('listings','digital');self::assertStringContainsString($listing['title'],$html);self::assertStringContainsString('Listing #'.$listing['id'].' · Product Version #'.$listing['product_version_id'],$html);self::assertStringContainsString(substr($readiness['hash'],0,16),$html);self::assertStringContainsString('Decision controls are withheld',$html);self::assertStringNotContainsString('>Approve Listing</button>',$html);self::assertStringNotContainsString($other['title'],$html);
  PortalActionAcceptanceFixture::invoke('LISTING_REVIEW_ACTION',['review_id'=>$id,'decision'=>'APPROVED'],true);self::assertSame('PENDING',$wpdb->get_var($wpdb->prepare('SELECT decision FROM '.Tables::listing_readiness_reviews().' WHERE id=%d',$id)));self::assertSame('DRAFT',$wpdb->get_var($wpdb->prepare('SELECT state FROM '.Tables::listings().' WHERE id=%d',$listing['id'])));
 }
 public function testAuditUnknownAndImmutableSubjectIdentitiesScopeBeforeWindowAndNeverExposeRawContext():void {
  $own=$this->product($this->candidate('digital','audit-own-'.wp_rand()));$foreign=$this->product($this->candidate('jewelry','audit-foreign-'.wp_rand()));$ownOp=$this->unknown($own);$foreignOp=$this->unknown($foreign);DigiForge\Security\Logger::write('own_subject_audit',['opaque_payload'=>'source-context-must-not-render'],'listing',(string)$ownOp['listing']['id']);DigiForge\Security\Logger::write('foreign_subject_audit',[],'listing',(string)$foreignOp['listing']['id']);DigiForge\Security\Logger::write('unassigned_subject_audit',[],'unassigned','1');
  $queryState=null;$window=(new DigiForge\Listings\EtsyReconciliationOperatorReadModel())->recent(1,$queryState,'digital');self::assertSame('AVAILABLE',$queryState);self::assertCount(1,$window);self::assertSame($ownOp['operation_id'],(int)$window[0]['id']);$html=$this->render('audit','digital',['df_etsy_operation'=>$ownOp['operation_id']]);self::assertStringContainsString($own['marker'].'-unknown-resource',$html);self::assertStringContainsString('own_subject_audit',$html);self::assertStringNotContainsString($foreign['marker'].'-unknown-resource',$html);self::assertStringNotContainsString('foreign_subject_audit',$html);self::assertStringNotContainsString('unassigned_subject_audit',$html);self::assertStringNotContainsString('source-context-must-not-render',$html);self::assertStringContainsString('df_view=listings',$html);
  $html=$this->render('audit','digital',['df_etsy_operation'=>$foreignOp['operation_id']]);self::assertStringNotContainsString($foreign['marker'].'-unknown-resource',$html);self::assertStringContainsString('Requested Etsy reconciliation evidence is unavailable',$html);$all=$this->render('audit','all');self::assertStringContainsString($own['marker'].'-unknown-resource',$all);self::assertStringContainsString($foreign['marker'].'-unknown-resource',$all);self::assertStringContainsString('unassigned_subject_audit',$all);self::assertStringNotContainsString('source-context-must-not-render',$all);
 }
 public function testIntegrationStoredProviderStatesAndSystemControlsAreSafeAndUnavailableReadsStayExplicit():void {
  global $wpdb;$now=current_time('mysql',true);$names=[];foreach(['etsy','printify','ai']as $provider){$name='source-'.$provider.'-'.wp_rand();$names[]=$name;self::assertSame(1,$wpdb->insert(Tables::integrations(),['provider'=>$provider,'connection_key'=>$name,'display_name'=>$name,'environment'=>'sandbox','status'=>'CONFIGURED','enabled'=>1,'config'=>wp_json_encode(['private_source_value'=>'connector-config-must-not-render']),'created_at'=>$now,'updated_at'=>$now]));}
  $html=$this->render('integrations','digital');foreach($names as $name)self::assertStringContainsString($name,$html);self::assertStringContainsString('CONFIGURED_UNVERIFIED',$html);self::assertStringNotContainsString('connector-config-must-not-render',$html);self::assertStringContainsString('never performs a provider connectivity test',$html);
  $table=Tables::integrations();$fail=static fn(string $sql):string=>str_contains($sql,'FROM '.$table)?'SELECT * FROM no_such_portal_connector_evidence':$sql;add_filter('query',$fail);try{$html=$this->render('integrations','digital');self::assertStringContainsString('Connector counts are UNKNOWN',$html);foreach($names as $name)self::assertStringNotContainsString($name,$html);}finally{remove_filter('query',$fail);}
  $html=$this->render('system','digital');self::assertStringContainsString('<span>Stop All</span><b class="is-on">ON</b>',$html);self::assertStringContainsString('<span>Automation Armed</span><b class="is-off">OFF</b>',$html);self::assertStringContainsString('<span>Etsy Publish</span><b class="is-off">OFF</b>',$html);
  $operator=self::factory()->user->create(['role'=>'subscriber']);$user=new WP_User($operator);$user->add_cap('manage_digiforge');$user->add_cap('manage_digiforge_research');wp_set_current_user($operator);self::assertStringNotContainsString($names[0],$this->render('integrations','digital'));self::assertStringNotContainsString('source-context-must-not-render',$this->render('audit','digital'));
 }
}
